import{c as a,Q as e,j as s,m as l}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"Lock","description":"","frontmatter":{},"headers":[{"level":1,"title":"Lock","slug":"lock"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/同步控制/核内同步/Mutex（ISASI）/Lock.md","filePath":"api/SIMD-API/基础API/同步控制/核内同步/Mutex（ISASI）/Lock.md"}'),n={name:"api/SIMD-API/基础API/同步控制/核内同步/Mutex（ISASI）/Lock.md"};function d(i,t,o,r,p,c){return e(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="lock" tabindex="-1">Lock <a class="header-anchor" href="#lock" aria-label="Permalink to &quot;Lock&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>根据MutexID获取Mutex，并阻塞当前流水指令队列，直到对应的MutexID被Unlock。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;pipe_t pipe&gt;</span></span>
<span class="line"><span>static __aicore__ inline void Lock(MutexID id)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>pipe</td><td>模板参数，表示流水类别。 支持的流水参考硬件流水类型。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>id</td><td>输入</td><td>进行流水同步管理的MutexID。 该id可通过用户自定义（范围为0-27）或者通过AllocMutexID/ReleaseMutexID进行申请释放。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>用户在使用Lock/Unlock时且自定义MutexID情况时，禁止同时使用<a href="./../../../资源管理/Pipe和Que框架/TQue/TQue.html">TQue</a>、<a href="./../../../资源管理/Pipe和Que框架/TQueBind/TQueBind.html">TQueBind</a>、<a href="./../../../资源管理/Pipe和Que框架/TBufPool/TBufPool.html">TBufPool</a>中的相关接口。</li><li>对于同一个MutexID，必须按照Lock/Unlock配套使用，且指定的pipe也需相同，即当且只有完成一个流水的Lock/Unlock之后，才能进行其余流水的操作。</li><li>相同流水之间存在数据依赖的场景，这种情况建议使用<a href="./../PipeBarrier(ISASI).html">PipeBarrier</a>接口。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整算子样例参考：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/06_sync_control/mutex" target="_blank" rel="noreferrer">Mutex样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 锁定 MTE2 流水线互斥锁，确保当前线程独占 MTE2 资源进行数据搬运</span></span>
<span class="line"><span>AscendC::Mutex::Lock&lt;PIPE_MTE2&gt;(mutexId);</span></span>
<span class="line"><span>AscendC::DataCopy(xLocal, src0Global[TILE_LENGTH * progress], TILE_LENGTH);</span></span>
<span class="line"><span>AscendC::DataCopy(yLocal, src1Global[TILE_LENGTH * progress], TILE_LENGTH);</span></span>
<span class="line"><span>// 解锁 MTE2 流水线，允许其他线程使用 MTE2</span></span>
<span class="line"><span>AscendC::Mutex::Unlock&lt;PIPE_MTE2&gt;(mutexId);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 锁定 Vector 流水线互斥锁，确保当前线程独占向量计算资源</span></span>
<span class="line"><span>AscendC::Mutex::Lock&lt;PIPE_V&gt;(mutexId);</span></span>
<span class="line"><span>AscendC::Add(zLocal, xLocal, yLocal, TILE_LENGTH);</span></span>
<span class="line"><span>// 解锁 Vector 流水线，释放计算资源供其他线程使用</span></span>
<span class="line"><span>AscendC::Mutex::Unlock&lt;PIPE_V&gt;(mutexId);</span></span></code></pre></div>`,19)])])}const x=a(n,[["render",d]]);export{u as __pageData,x as default};
